from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from . import models, schemas


def create_router(get_session: Callable[[], Iterator[Session]]) -> APIRouter:
    router = APIRouter()

    @router.patch("/api/journals" + "/{item_id}", response_model=schemas.JournalRead)
    def patch(
        item_id: int, payload: schemas.JournalPatch, db: Session = Depends(get_session)
    ) -> models.Journal:
        row = db.get(models.Journal, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        for key, value in payload.model_dump(exclude_unset=True).items():
            setattr(row, key, value)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.get("/api/journals", response_model=list[schemas.JournalRead])
    def list_items(
        archived: bool | None = None,
        before: date | None = None,
        limit: int = Query(default=20, ge=1, le=25),
        offset: int = Query(default=0, ge=0),
        db: Session = Depends(get_session),
    ) -> list[models.Journal]:
        stmt = select(models.Journal)
        if archived is not None:
            stmt = stmt.where(models.Journal.archived == archived)
        if before is not None:
            stmt = stmt.where(models.Journal.ends_on < before)
        stmt = stmt.order_by(models.Journal.id).limit(limit).offset(offset)
        return list(db.scalars(stmt))

    @router.post("/api/journals", response_model=schemas.JournalRead, status_code=201)
    def create(
        payload: schemas.JournalCreate, db: Session = Depends(get_session)
    ) -> models.Journal:
        row = models.Journal(**payload.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.delete("/api/journals" + "/{item_id}", status_code=204)
    def delete(item_id: int, db: Session = Depends(get_session)) -> None:
        row = db.get(models.Journal, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        db.delete(row)
        db.commit()

    @router.get("/api/journals" + "/{item_id}", response_model=schemas.JournalRead)
    def get(item_id: int, db: Session = Depends(get_session)) -> models.Journal:
        row = db.get(models.Journal, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        return row

    return router

