            stmt = stmt.where(models.Bundle.ready == ready)
        if before is not None:
            stmt = stmt.where(models.Bundle.planned_on < before)
        stmt = stmt.order_by(models.Bundle.id).limit(limit).offset(offset)
        return list(db.scalars(stmt))

    @router.post("/bundles", response_model=schemas.BundleRead, status_code=201)
    def create(
        payload: schemas.BundleCreate, db: Session = Depends(get_session)
    ) -> models.Bundle:
        row = models.Bundle(**payload.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
