        self.assertEqual(dated.status_code, 200, dated.text)
        self.assertEqual(dated.json()["planned_on"], "2030-01-02")
        self.assertEqual(
            [row["id"] for row in self.client.get(
                "/api/schedules", params={"enabled": True, "before": "2030-01-03"}
            ).json()], [item_id]
        )
        self.assertEqual(self.client.get(
            "/api/schedules", params={"before": "2030-01-02"}
        ).json(), [])
        self.assertEqual(self.client.get(
            "/api/schedules", params={"before": "not-a-date"}
        ).status_code, 422)
        self.assertEqual(self.client.delete("/api/schedules" + f"/{item_id}").status_code, 204)
        self.assertEqual(self.client.get("/api/schedules" + f"/{item_id}").status_code, 404)
